// Color por zona (HSL distribuido)
export const ZONE_COLOR = {};
ZONES.forEach((z, i) => {
  const hue = Math.round((i / ZONES.length) * 360);
  ZONE_COLOR[z] = `hsl(${hue}, 34%, 54%)`;
});
